using UnityEngine;
using DD.Prototype.Weapons;

namespace DD.Prototype.Characters
{
    /// <summary>AP-024D v009 calibration, socket_mag_l → reload part PIVOT (metres).
    /// FBX preserves object-local axes below its X270 root; Unity mirrors FBX local X.
    /// Thus local matrices use C M C, C=diag(-1,1,1,1), never the root axis rotation twice.
    /// Source: AP-024/validation/ap024d_grip_calibration_b2d_v3.json; generated by S-06 E5.</summary>
    public static class ReloadPartCalibration
    {
        public static Matrix4x4 FromBlenderLocal(Matrix4x4 value)
        {
            Matrix4x4 mirror = Matrix4x4.Scale(new Vector3(-1f, 1f, 1f));
            return mirror * value * mirror;
        }

        public static bool TryGet(string key, out Matrix4x4 socketToPart)
        {
            switch (key)
            {
                case "lmg_1": socketToPart = FromBlenderLocal(new Matrix4x4(new Vector4(0.0764463171f, -0.508785307f, 0.857492507f, 0f), new Vector4(0.141112804f, -0.845831037f, -0.514446855f, 0f), new Vector4(0.987037241f, 0.160330847f, 0.00713540241f, 0f), new Vector4(0.102622762f, 0.0102613959f, -0.132437617f, 1f))); return true;
                case "lmg_2": socketToPart = FromBlenderLocal(new Matrix4x4(new Vector4(0.367963344f, -0.178408563f, 0.912563741f, 0f), new Vector4(0.91978246f, -0.0741183311f, -0.38536483f, 0f), new Vector4(0.136390567f, 0.981160343f, 0.136824787f, 0f), new Vector4(0.0408510305f, 0.0279337186f, -0.13965708f, 1f))); return true;
                case "sw_gel": socketToPart = FromBlenderLocal(new Matrix4x4(new Vector4(-0.351156175f, -0.272079706f, 0.895913601f, 0f), new Vector4(0.909600616f, -0.326069474f, 0.257497072f, 0f), new Vector4(0.22207047f, 0.90534538f, 0.361985564f, 0f), new Vector4(0.0585069358f, -0.0714620575f, -0.122711152f, 1f))); return true;
                case "sw_arc": socketToPart = FromBlenderLocal(new Matrix4x4(new Vector4(0.11196363f, -0.849544048f, 0.515497684f, 0f), new Vector4(0.552291274f, 0.484457374f, 0.678435266f, 0f), new Vector4(-0.826097965f, 0.208745047f, 0.523438036f, 0f), new Vector4(0.0846040398f, 0.00634167204f, -0.122417644f, 1f))); return true;
                default: socketToPart = Matrix4x4.identity; return false;
            }
        }

        public static bool TryStep(CharacterAnimationEvent e, out MagazineStep step)
        {
            if (e == CharacterAnimationEvent.CanisterOut || e == CharacterAnimationEvent.CellOut) { step = MagazineStep.Detach; return true; }
            if (e == CharacterAnimationEvent.CanisterIn || e == CharacterAnimationEvent.CellIn) { step = MagazineStep.Insert; return true; }
            return WeaponMagazineOwnership.TryStepFor(e, out step);
        }

        public static string PartName(string key) => key == "sw_gel" ? "part_canister" : key == "sw_arc" ? "part_cell_1" : "part_mag";
        public static readonly string[] ArcGroup = { "part_cell_1", "part_cell_2", "part_cell_3" };

        public static void ConfigureSocket(Transform socket, string key)
        {
            if (socket == null) return;
            ReloadPartSocket row = socket.GetComponent<ReloadPartSocket>();
            if (row == null) row = socket.gameObject.AddComponent<ReloadPartSocket>();
            row.Key = key;
        }
    }
}
